package com.ethk3.novaonepro.strategyv2;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;
public class RepairModelReplayR30Test {
 static ModelSurfaceProviderR30.Pit pit(){return new ModelSurfaceProviderR30.Pit(100,99,1,"actual-input",AtomNetR27.positionedInput(new double[]{.2,.8},1),19000,20000,20000,30000);}
 static ModelSurfaceProviderR30.FrozenModelRef model(long seed,long available){return new ModelSurfaceProviderR30.FrozenModelRef(new AtomNetR27(12,seed).encode(),99,available);}
 @Test public void actualTwoModelsUseOnePastInputAndNoLabel(){ModelSurfaceProviderR30.Pit pit=pit();ModelSurfaceProviderR30.FrozenModelRef current=model(7,11000),old=model(6,10000);ModelSurfaceProviderR30.Surface prediction=ModelSurfaceProviderR30.predict(pit,current);Map<String,Object> p=ModelReplayStudyR30R1.freeze(new OnlineResearchWindowR30R1.Window(StatsR27.sha256("registered-online-window"),100,200,1000),pit,prediction,old);assertEquals("ONLINE_RESEARCH",p.get("role"));assertNotEquals(p.get("currentModelHash"),p.get("previousModelHash"));assertEquals(StatsR27.sha256(StoreR27.pack(prediction.probabilities())),p.get("currentProbabilityHash"));assertFalse(p.containsKey("actual"));assertEquals(p.get("receiptHash"),ModelReplayStudyR30R1.verified(JsonR27.write(p)).get("receiptHash"));}
 @Test(expected=IllegalStateException.class) public void collectionRegisteredAfterFreezeCannotBeInvented(){ModelSurfaceProviderR30.Pit p=pit();ModelReplayStudyR30R1.freeze(new OnlineResearchWindowR30R1.Window(StatsR27.sha256("late"),100,200,20001),p,ModelSurfaceProviderR30.predict(p,model(7,11000)),model(6,10000));}
 @Test public void changedReceiptIsRejectedAndLabelsAreNotInTheFreezeIdentity(){ModelSurfaceProviderR30.Pit pit=pit();Map<String,Object> p=ModelReplayStudyR30R1.freeze(new OnlineResearchWindowR30R1.Window(StatsR27.sha256("window"),100,200,1000),pit,ModelSurfaceProviderR30.predict(pit,model(7,11000)),model(6,10000));p.put("position",2);try{ModelReplayStudyR30R1.verified(JsonR27.write(p));fail("tampered receipt");}catch(IllegalStateException expected){assertTrue(expected.getMessage().contains("HASH"));}}
 @Test public void replayAllocationNeedsActualEligibleOnlineBlockEvidenceAndNeverResetsTheModel(){Map<String,Object> e=new LinkedHashMap<>();e.put("protocol",ModelReplayStudyR30R1.VERSION);e.put("role","ONLINE_RESEARCH");e.put("formalTablesRead",false);e.put("status","DESCRIPTIVE_ONLINE_RESEARCH_ONLY");e.put("completeBlocks",4);e.put("calendarIssues",256);e.put("missingObservedIssues",0);e.put("upper95",-.01);assertEquals("OLD48_RECENT15",ModelReplayStudyR30R1.replayPolicy(e,"UNIFORM_63"));e.put("role","FUTURE");assertEquals("UNIFORM_63",ModelReplayStudyR30R1.replayPolicy(e,"UNIFORM_63"));e.put("role","ONLINE_RESEARCH");e.put("upper95",Double.NaN);assertEquals("UNIFORM_63",ModelReplayStudyR30R1.replayPolicy(e,"UNIFORM_63"));e.put("upper95",-.01);e.put("missingObservedIssues",1);assertEquals("UNIFORM_63",ModelReplayStudyR30R1.replayPolicy(e,"UNIFORM_63"));}
 @Test public void replayModeAndEvidenceSurviveLosslessOuterStateCodec(){AtomNetSessionR30 state=new AtomNetSessionR30(StatsR27.sha256("host-dataset"),"202610300100",100,12,100,100,0);state.replayPolicy="OLD48_RECENT15";state.replayEvidenceRun=StatsR27.sha256("host-online-evidence");state.replayPolicyChanges=1;byte[] beforeNet=state.trainer.net.encode();long rng=state.trainer.rng.state;byte[] bytes=state.encode();AtomNetSessionR30 restored=AtomNetSessionR30.decode(bytes,StatsR27.sha256(bytes));assertEquals(state.replayPolicy,restored.replayPolicy);assertEquals(state.replayEvidenceRun,restored.replayEvidenceRun);assertEquals(1,restored.replayPolicyChanges);assertEquals(rng,restored.trainer.rng.state);assertArrayEquals(beforeNet,restored.trainer.net.encode());assertArrayEquals(bytes,restored.encode());}
}
